using App.Tables.AuditLogTable;
using App.Tables.Categories;
using App.Tables.Customers;
using App.Tables.OrderLines;
using App.Tables.Orders;
using App.Tables.ProductTags;
using App.Tables.Products;
using App.Tables.Tags;
using Microsoft.EntityFrameworkCore;

namespace App;

/// <summary>The tables of the database, mapped as the database has them. It never migrates: the database already exists.</summary>
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Customer> Customers => Set<Customer>();
    public DbSet<Category> Categories => Set<Category>();
    public DbSet<Product> Products => Set<Product>();
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<OrderLine> OrderLines => Set<OrderLine>();
    public DbSet<Tag> Tags => Set<Tag>();
    public DbSet<ProductTag> ProductTags => Set<ProductTag>();
    public DbSet<AuditLog> AuditLogRows => Set<AuditLog>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<Customer>(entity =>
        {
            entity.ToTable("customers");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("id");
            entity.Property(e => e.Email).HasColumnName("email").HasMaxLength(120);
            entity.Property(e => e.PasswordHash).HasColumnName("password_hash");
            entity.Property(e => e.CreatedAt).HasColumnName("created_at").IsRequired().HasDefaultValueSql("CURRENT_TIMESTAMP(6)");
            entity.HasIndex(e => e.Email).IsUnique().HasDatabaseName("uq_customers_email");
        });

        model.Entity<Category>(entity =>
        {
            entity.ToTable("categories");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("id");
            entity.Property(e => e.Name).HasColumnName("name").HasMaxLength(60);
            entity.HasIndex(e => e.Name).IsUnique();
        });

        model.Entity<Product>(entity =>
        {
            entity.ToTable("products", t =>
            {
                t.HasCheckConstraint("ck_products_1", "price >= 0");
            });
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("id");
            entity.Property(e => e.CategoryId).HasColumnName("category_id");
            entity.Property(e => e.Name).HasColumnName("name").HasMaxLength(100);
            entity.Property(e => e.Price).HasColumnName("price").HasPrecision(10, 2);
            entity.Property(e => e.Status).HasColumnName("status").HasMaxLength(10);
            entity.Property(e => e.Version).HasColumnName("version").IsRequired().HasDefaultValue(1);
            entity.Property(e => e.DeletedAt).HasColumnName("deleted_at");
            entity.HasIndex(e => e.Status).HasDatabaseName("ix_products_status");
            entity.HasIndex(e => e.CategoryId);
            entity.HasOne<Category>()
                .WithMany()
                .HasForeignKey(e => e.CategoryId)
                .OnDelete(DeleteBehavior.NoAction)
                .HasConstraintName("fk_products_category");
        });

        model.Entity<Order>(entity =>
        {
            entity.ToTable("orders");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("id");
            entity.Property(e => e.CustomerId).HasColumnName("customer_id");
            entity.Property(e => e.PlacedAt).HasColumnName("placed_at").IsRequired().HasDefaultValueSql("CURRENT_TIMESTAMP(6)");
            entity.HasOne<Customer>()
                .WithMany()
                .HasForeignKey(e => e.CustomerId)
                .OnDelete(DeleteBehavior.NoAction);
        });

        model.Entity<OrderLine>(entity =>
        {
            entity.ToTable("order_lines");
            entity.HasKey(e => new { e.OrderId, e.Line });
            entity.Property(e => e.OrderId).HasColumnName("order_id");
            entity.Property(e => e.Line).HasColumnName("line");
            entity.Property(e => e.ProductId).HasColumnName("product_id");
            entity.Property(e => e.Quantity).HasColumnName("quantity");
            entity.HasOne<Order>()
                .WithMany()
                .HasForeignKey(e => e.OrderId)
                .OnDelete(DeleteBehavior.Cascade);
            entity.HasOne<Product>()
                .WithMany()
                .HasForeignKey(e => e.ProductId)
                .OnDelete(DeleteBehavior.Restrict);
        });

        model.Entity<Tag>(entity =>
        {
            entity.ToTable("tags");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("id");
            entity.Property(e => e.Label).HasColumnName("label").HasMaxLength(30);
        });

        model.Entity<ProductTag>(entity =>
        {
            entity.ToTable("product_tags");
            entity.HasKey(e => new { e.ProductId, e.TagId });
            entity.Property(e => e.ProductId).HasColumnName("product_id");
            entity.Property(e => e.TagId).HasColumnName("tag_id");
            entity.HasOne<Product>()
                .WithMany()
                .HasForeignKey(e => e.ProductId)
                .OnDelete(DeleteBehavior.Cascade);
            entity.HasOne<Tag>()
                .WithMany()
                .HasForeignKey(e => e.TagId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        model.Entity<AuditLog>(entity =>
        {
            entity.ToTable("audit_log");
            // The table has no primary key: EF Core reads it, and never writes it
            entity.HasNoKey();
            entity.Property(e => e.At).HasColumnName("at");
            entity.Property(e => e.Message).HasColumnName("message");
        });
    }
}

