using App;
using App.Common;
using App.Errors;
using Microsoft.EntityFrameworkCore;

namespace App.Tables.AuditLogTable;

/// <summary>Keeps audit_log rows in the database, through AppDbContext. A write joins the transaction already open, or is committed at once.</summary>
public class SqlAuditLogRepository(AppDbContext db) : IAuditLogRepository
{
    public async Task<CursorPage<AuditLog>> ListAsync(IReadOnlyList<object>? after, int limit)
    {
        IQueryable<AuditLog> query = db.AuditLogRows;
        if (after is not null)
        {
            var k0 = (DateTimeOffset)after[0];
            var k1 = (string)after[1];
            query = query.Where(e => (e.At > k0) || (e.At == k0 && e.Message.CompareTo(k1) > 0));
        }
        var rows = await query.OrderBy(e => e.At).ThenBy(e => e.Message).Take(limit + 1).ToListAsync();
        var items = rows.Take(limit).ToList();
        return new CursorPage<AuditLog>(items, rows.Count > limit ? [items[^1].At, items[^1].Message] : null);
    }

    /// <summary>Saves the changes; a database refusal (a unique value, a row still pointed to) becomes a ConflictException.</summary>
    private async Task SaveAsync()
    {
        try
        {
            await db.SaveChangesAsync();
        }
        catch (DbUpdateException error)
        {
            db.ChangeTracker.Clear();
            throw new ConflictException("AuditLog", $"the database refused the change: {error.InnerException?.Message ?? error.Message}");
        }
    }
}

