namespace App.Tables.Categories;

/// <summary>Keeps categories rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryCategoryRepository : ICategoryRepository
{
    private readonly Dictionary<string, Category> rows = [];
    private long nextId = 1;

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Category row) => [row.Id];

    private static string KeyText(Category row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Category> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Category?> FindByIdAsync(long id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<CursorPage<Category>> ListAsync(IReadOnlyList<object>? after, int limit)
    {
        var rows = Visible().Where(row => after is null || Compare(KeyOf(row), after) > 0).ToList();
        var items = rows.Take(limit).ToList();
        return Task.FromResult(new CursorPage<Category>(items, rows.Count > limit ? KeyOf(items[^1]) : null));
    }

    public Task<Category?> FindByNameAsync(string name)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Name, name)));
    }

    public Task<Category> InsertAsync(Category entity)
    {
        if (entity.Id == 0) entity.Id = nextId++;
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Category> UpdateAsync(Category entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Category entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }
}

