    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("OrderId");
            if (value is null)
                if (creating || values.ContainsKey("OrderId")) errors.Add(new FieldError("order_id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Line");
            if (value is null)
                if (creating || values.ContainsKey("Line")) errors.Add(new FieldError("line", "is required"));
        }
        {
            var value = values.GetValueOrDefault("ProductId");
            if (value is null)
                if (creating || values.ContainsKey("ProductId")) errors.Add(new FieldError("product_id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Quantity");
            if (value is null)
                if (creating || values.ContainsKey("Quantity")) errors.Add(new FieldError("quantity", "is required"));
        }
        {
            var orderId = values.TryGetValue("OrderId", out var givenOrderId) ? (long?)givenOrderId : current?.OrderId;
