    {
        if (values.TryGetValue("OrderId", out var orderId)) entity.OrderId = (long)orderId!;
        if (values.TryGetValue("Line", out var line)) entity.Line = (int)line!;
        if (values.TryGetValue("ProductId", out var productId)) entity.ProductId = (long)productId!;
