    Task<CursorPage<Tag>> ListAsync(IReadOnlyList<object>? after, int limit);

    /// <summary>Stores a new row; the values the database fills are read back.</summary>
    Task<Tag> InsertAsync(Tag entity);

    /// <summary>Stores the changes made to a row read from this repository.</summary>
    Task<Tag> UpdateAsync(Tag entity);

