using App.Common;

namespace App.Tables.Tags;

/// <summary>Keeps tags rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryTagRepository : ITagRepository
{
    private readonly Dictionary<string, Tag> rows = [];
    private long nextId = 1;

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Tag row) => [row.Id];

    private static string KeyText(Tag row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Tag> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Tag?> FindByIdAsync(long id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<CursorPage<Tag>> ListAsync(IReadOnlyList<object>? after, int limit)
    {
        var rows = Visible().Where(row => after is null || Compare(KeyOf(row), after) > 0).ToList();
        var items = rows.Take(limit).ToList();
        return Task.FromResult(new CursorPage<Tag>(items, rows.Count > limit ? KeyOf(items[^1]) : null));
    }

    public Task<Tag> InsertAsync(Tag entity)
    {
        if (entity.Id == 0) entity.Id = nextId++;
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Tag> UpdateAsync(Tag entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Tag entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }
}

