using App;
using App.Common;
using App.Errors;
using Microsoft.EntityFrameworkCore;

namespace App.Tables.Tags;

/// <summary>Keeps tags rows in the database, through AppDbContext. A write joins the transaction already open, or is committed at once.</summary>
public class SqlTagRepository(AppDbContext db) : ITagRepository
{
    public async Task<Tag?> FindByIdAsync(long id)
    {
        return await db.Tags.Where(e => e.Id == id).FirstOrDefaultAsync();
    }

    public async Task<CursorPage<Tag>> ListAsync(IReadOnlyList<object>? after, int limit)
    {
        IQueryable<Tag> query = db.Tags;
        if (after is not null)
        {
            var k0 = (long)after[0];
            query = query.Where(e => e.Id > k0);
        }
        var rows = await query.OrderBy(e => e.Id).Take(limit + 1).ToListAsync();
        var items = rows.Take(limit).ToList();
        return new CursorPage<Tag>(items, rows.Count > limit ? [items[^1].Id] : null);
    }

    public async Task<Tag> InsertAsync(Tag entity)
    {
        db.Tags.Add(entity);
        await SaveAsync();
        return entity;
    }

    public async Task<Tag> UpdateAsync(Tag entity)
    {
        db.Tags.Update(entity);
        await SaveAsync();
        return entity;
    }

    public async Task DeleteAsync(Tag entity)
    {
        db.Tags.Remove(entity);
        await SaveAsync();
    }

    /// <summary>Saves the changes; a database refusal (a unique value, a row still pointed to) becomes a ConflictException.</summary>
    private async Task SaveAsync()
    {
        try
        {
            await db.SaveChangesAsync();
        }
        catch (DbUpdateException error)
        {
            db.ChangeTracker.Clear();
            throw new ConflictException("Tag", $"the database refused the change: {error.InnerException?.Message ?? error.Message}");
        }
    }
}

