using App;
using App.Common;
using App.Errors;

namespace App.Tables.Tags;

/// <summary>Operations on tags. Each write runs in its own transaction.</summary>
public class TagService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "tags" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Tag? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Label");
            if (value is null)
                if (creating || values.ContainsKey("Label")) errors.Add(new FieldError("label", "is required"));
            else
            {
                if (value is string text && text.Length > 30) errors.Add(new FieldError("label", "is longer than 30 characters"));
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Tag", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Tag? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Tag entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Label", out var label)) entity.Label = (string)label!;
    }

    /// <summary>The Tag with this key; NotFoundException when there is none.</summary>
    private static async Task<Tag> FindAsync(IUnitOfWork uow, long id) =>
        await uow.Tags.FindByIdAsync(id) ?? throw new NotFoundException("Tag", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(TagChanges changes)
    {
        var values = new Dictionary<string, object?>();
        values["Label"] = changes.Label;
        return values;
    }

    /// <summary>Stores a new Tag after checking it.</summary>
    public async Task<Tag> CreateTagAsync(Tag tag)
    {
        var values = new Dictionary<string, object?>();
        if (tag.Label is not null) values["Label"] = tag.Label;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Tags.InsertAsync(tag);
        });
    }

    /// <summary>The Tag with this key; NotFoundException when there is none.</summary>
    public async Task<Tag> GetTagAsync(long id) => await FindAsync(uow, id);

    /// <summary>A page of tags after the key after (null for the first page), by primary key.</summary>
    public async Task<CursorPage<Tag>> ListTagsAsync(IReadOnlyList<object>? after, int limit) => await uow.Tags.ListAsync(after, limit);

    /// <summary>Changes the given values of a Tag.</summary>
    public async Task<Tag> UpdateTagAsync(long id, TagChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return await uow.Tags.UpdateAsync(current);
        });
    }

    /// <summary>Deletes a Tag.</summary>
    public async Task DeleteTagAsync(long id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Tags.DeleteAsync(current);
        });
    }
}

